"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["70543"],{81125(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.nota_maxima_invalida","status":422,"titulo":"A nota m\xe1xima, quando informada, deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.nota_maxima_invalida","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["Uma das etapas do corpo do pedido informou `notaMaxima` igual a zero ou negativa. Uma\\nescala que vai de zero a zero, ou abaixo dela, n\xe3o comporta nota alguma, e nenhuma\\nnota m\xednima caberia nela.","O campo \xe9 opcional na grava\xe7\xe3o: o processo em rascunho pode n\xe3o ter decidido ainda a\\nescala da etapa. Esta recusa vale s\xf3 para o valor declarado e contradit\xf3rio, e ela\\nchega no array `errors[]`, no campo `notaMaxima` da etapa, junto das demais viola\xe7\xf5es\\nda mesma defini\xe7\xe3o de etapas."],"comoResolver":["Informe uma `notaMaxima` maior que zero (por exemplo, 10 ou 1000), ou omita o campo\\nenquanto o processo estiver em rascunho.","A nota m\xe1xima s\xf3 \xe9 obrigat\xf3ria na publica\xe7\xe3o, e s\xf3 na etapa com nota que n\xe3o \xe9 do\\nENEM. Se a etapa tiver nota m\xednima, ela n\xe3o pode passar da m\xe1xima; e a m\xe1xima deve\\nser m\xfaltipla do passo do lan\xe7amento, quando houver passo. Se a resposta trouxer mais\\nde uma viola\xe7\xe3o em `errors[]`, corrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);